  static const Map<String, List<String>> _weekdayLetters = {
    'en': ['M', 'T', 'W', 'T', 'F', 'S', 'S'],
    'hi': ['सो', 'मं', 'बु', 'गु', 'शु', 'श', 'र'],
    'bn': ['সো', 'ম', 'বু', 'বৃ', 'শু', 'শ', 'র'],
    'as': ['সো', 'ম', 'বু', 'বৃ', 'শু', 'শ', 'দে'],
    'mni': ['নি', 'লৈ', 'য়ু', 'শ', 'ই', 'থা', 'নো'],
    'miz': ['T', 'T', 'N', 'N', 'Z', 'I', 'C'],
    'kn': ['ಸೋ', 'ಮಂ', 'ಬು', 'ಗು', 'ಶು', 'ಶ', 'ಭಾ'],
    'te': ['సో', 'మం', 'ಬು', 'గు', 'శు', 'శ', 'ఆ'],
    'mr': ['सो', 'मं', 'बु', 'गु', 'शु', 'श', 'र'],
  };

  static const List<String> _defaultWeekdays = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
  static const List<String> _defaultMonths = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  static const List<String> _defaultWeekdayLetters = ['M', 'T', 'W', 'T', 'F', 'S', 'S'];

  static String getWeekdayLetter(DateTime date, {String? language}) {
    final code = normalizeLangCode(language);
    final letters = _weekdayLetters[code] ?? _weekdayLetters['en'] ?? _defaultWeekdayLetters;
    final index = (date.weekday - 1).clamp(0, letters.length - 1);
    return letters[index];
  }

  static String formatDate(
    DateTime date, {
    String? language,
    bool includeWeekday = true,
    bool includeYear = true,
  }) {
    final code = normalizeLangCode(language);
    final weekdays = _shortWeekdays[code] ?? _shortWeekdays['en'] ?? _defaultWeekdays;
    final months = _shortMonths[code] ?? _shortMonths['en'] ?? _defaultMonths;

    final weekdayIdx = (date.weekday - 1).clamp(0, weekdays.length - 1);
    final monthIdx = (date.month - 1).clamp(0, months.length - 1);
    final weekdayStr = weekdays[weekdayIdx];
    final monthStr = months[monthIdx];
    final day = date.day;
    final year = date.year;

    if (code == 'en' || code == 'miz') {
      final datePart = includeYear ? '$monthStr $day, $year' : '$monthStr $day';
      return includeWeekday ? '$weekdayStr, $datePart' : datePart;
    } else {
      final datePart = includeYear ? '$day $monthStr $year' : '$day $monthStr';
      return includeWeekday ? '$weekdayStr, $datePart' : datePart;
    }
  }

  static String normalizeLangCode(String? language) {
    if (language == null) return 'en';
    final lower = language.toLowerCase().trim();
    if (lower == 'mr' ||
        lower.startsWith('mr_') ||
        lower.startsWith('mr-') ||
        lower.contains('मराठी') ||
        lower.contains('marathi')) {
      return 'mr';
    }
    if (lower == 'kn' ||
        lower.startsWith('kn_') ||
        lower.startsWith('kn-') ||
        lower.contains('ಕನ್ನಡ') ||
        lower.contains('kannada')) {
      return 'kn';
    }
    if (lower == 'te' ||
        lower.startsWith('te_') ||
        lower.startsWith('te-') ||
        lower.contains('తెలుగు') ||
        lower.contains('telugu')) {
      return 'te';
    }
    if (lower == 'hi' ||
        lower.startsWith('hi_') ||
        lower.startsWith('hi-') ||
        lower.contains('हिंदी') ||
        lower.contains('hindi')) {
      return 'hi';
    }
    if (lower == 'bn' ||
        lower.startsWith('bn_') ||
        lower.startsWith('bn-') ||
        lower.contains('বাংলা') ||
        lower.contains('bengali')) {
      return 'bn';
    }
    if (lower == 'as' ||
        lower.startsWith('as_') ||
        lower.startsWith('as-') ||
        lower.contains('অসমীয়া') ||
        lower.contains('assamese')) {
      return 'as';
    }
    if (lower == 'mni' ||
        lower.startsWith('mni_') ||
        lower.startsWith('mni-') ||
        lower.contains('মণিপুরী') ||
        lower.contains('মৈতৈলোন') ||
        lower.contains('manipuri')) {
      return 'mni';
    }
    if (lower == 'miz' ||
        lower.startsWith('miz_') ||
        lower.startsWith('miz-') ||
        lower.contains('mizo')) {
      return 'miz';
    }
    return 'en';
  }

  static String get(
    String? language,
    String key, {
    Map<String, String>? params,
  }) {
    final code = normalizeLangCode(language);
    final map = _localizedValues[code] ?? _localizedValues['en'] ?? {};
    var str = map[key] ?? _localizedValues['en']?[key] ?? key;
    if (params != null) {
      params.forEach((k, v) {
        str = str.replaceAll('{$k}', v);
      });
    }
    return str;
  }

  static String tr(
    BuildContext context,
    String key, {
    Map<String, String>? params,
  }) {
    try {
      final appProvider = Provider.of<AppProvider>(context, listen: true);
      return get(appProvider.userLanguage, key, params: params);
    } catch (_) {
      try {
        final appProvider = Provider.of<AppProvider>(context, listen: false);
        return get(appProvider.userLanguage, key, params: params);
      } catch (_) {
        return get('en', key, params: params);
      }
    }
  }

  static String trRead(
    BuildContext context,
    String key, {
    Map<String, String>? params,
  }) {
    try {
      final appProvider = context.read<AppProvider>();
      return get(appProvider.userLanguage, key, params: params);
    } catch (_) {
      return get('en', key, params: params);
    }
  }
}

extension AppTranslationExtension on BuildContext {
  String tr(String key, {Map<String, String>? params}) =>
      AppTranslations.tr(this, key, params: params);

  String formatDate(
    DateTime date, {
    bool includeWeekday = true,
    bool includeYear = true,
  }) {
    String? lang = 'en';
    try {
      final appProvider = Provider.of<AppProvider>(this, listen: false);
      lang = appProvider.userLanguage;
    } catch (_) {}
    return AppTranslations.formatDate(
      date,
      language: lang,
      includeWeekday: includeWeekday,
      includeYear: includeYear,
    );
  }

  String getWeekdayLetter(DateTime date) {
    String? lang = 'en';
    try {
      final appProvider = Provider.of<AppProvider>(this, listen: false);
      lang = appProvider.userLanguage;
    } catch (_) {}
    return AppTranslations.getWeekdayLetter(date, language: lang);
  }
}

