  String localizeVillage(String? village) {
    if (village == null || village.trim().isEmpty) return '';
    final trimmed = village.trim();
    final lower = trimmed.toLowerCase();

    // 1. Direct key match (case-insensitive)
    final mappedKey = _villageKeyMap[lower];
    if (mappedKey != null) {
      return tr(mappedKey);
    }

    // 2. Reverse lookup in case string is already in one of the 6 languages
    final revKey = _reverseLookup[trimmed] ?? _reverseLookup[lower];
    if (revKey != null) {
      return tr(revKey);
    }

    // 3. Multi-village delimiter check (comma or slash)
    if (trimmed.contains(',') || trimmed.contains('/')) {
      final delimiter = trimmed.contains(',') ? ',' : '/';
      final parts = trimmed.split(delimiter);
      final localizedParts = parts.map((part) => localizeVillage(part.trim())).toList();
      return localizedParts.join(delimiter == ',' ? ', ' : ' / ');
    }

    // 4. Token-level decomposition for "<Village> <Modifier>" patterns
    final subResult = _tryLocalizeTokens(trimmed);
    if (subResult != null) {
      return subResult;
    }

    return trimmed;
  }

  String? _tryLocalizeTokens(String input) {
    final tokens = input.split(RegExp(r'\s+'));
    if (tokens.length >= 2) {
      final root = tokens[0].toLowerCase();
      final rest = tokens.sublist(1).join(' ').toLowerCase();

      final rootKey = _villageKeyMap[root];
      if (rootKey != null) {
        final localizedRoot = tr(rootKey);
        final modKey = _villageKeyMap[rest] ?? _villageKeyMap['cluster $rest'];
        if (modKey != null) {
          final localizedMod = tr(modKey);
          return '$localizedRoot $localizedMod';
        }
      }
    }
    return null;
  }
}
